-- OCIO Mandate Target Manager: Harbor Lite's own schema additions, sample records and rules.
-- Generated from surfaces/ocio/prototype.html's example data. Safe to run again.
--
-- Everything here belongs to Harbor Lite:
--   * reference lists OCIO_STRATEGY_TREE, OCIO_STRUCTURE_TREE, OCIO_REGION, OCIO_TARGET_BASIS,
--     OCIO_ASSET_TYPE, OCIO_TARGET_HIERARCHY
--   * the entity type OCIO_TARGET ("Allocation Target"): one record per fund, hierarchy and
--     level, linked to its fund by OCIO_TARGET_FUND. Each minimum, target and maximum, in
--     dollars, investment count and percent, is its own attribute on that record, so every
--     value has its own sources and history. No target is kept inside a JSON value.
--   * one ISSUER record per manager (codes OCIO-ISS-*), with every security linked to its
--     manager by SECURITY_ISSUER. A security needs an issuer; the manager's name on the
--     security is kept, but it is not a substitute for the record.
--   * attributes OCIO_* on the global FUND, SECURITY, POSITION and DEAL_FUNDING_PLAN types
--   * the security template OCIO_SECURITY_FUND ("Fund"), used by securities whose asset type is Fund
--   * records with codes OCIO-*: 3 client programs and 6 mandate sleeves (FUND, linked by
--     FUND_PARENT), each commitment as a POSITION on a SECURITY, and the pipeline as DEAL,
--     DEAL_TRANCHE and SECURITY
--   * compliance rules OCIO_*, enrolled per sleeve through rule_thresholds
--   * the OCIO module, which grants the ocio surface and its entity types
-- Global attributes the surface reuses are not changed: FUND_TOTAL_COMMITMENTS,
-- INCEPTION_DATE, FUND_INVESTMENT_PERIOD_END, FUND_BASE_CURRENCY, FUND_IS_ALLOCATION_ELIGIBLE,
-- SECURITY_LABEL, SECURITY_ISSUER_NAME, CURRENCY, TRADE_DATE, POSITION_CURRENCY, DEAL_STAGE,
-- DEAL_TARGET_CLOSE_DATE, DEAL_DESCRIPTION, DEAL_VALUE, TRANCHE_HOLD_AMOUNT, TRANCHE_SIZE,
-- TRANCHE_RANK, FUNDING_STATUS.

DO $$
DECLARE
    v_client uuid;
    v_src uuid;
BEGIN
    SELECT id INTO v_client FROM tenancy.clients WHERE client_code = 'HARBOR_LITE';
    SELECT id INTO v_src FROM entity_instances.source_registry WHERE source_code = 'INTERNAL' ORDER BY precedence_rank LIMIT 1;
    IF v_client IS NULL OR v_src IS NULL THEN
        RAISE NOTICE 'Skipping the OCIO seed: client % source %', v_client, v_src;
        RETURN;
    END IF;

    -- ---------- entity type: allocation target ----------
    -- A target belongs to one fund at one level of one hierarchy. It is a record of its own so
    -- that each of its values is an attribute a person can edit, a rule can read and anyone can
    -- right-click for sources.
    INSERT INTO metadata_register.domain_types (
        domain_code, domain_name, description, client_id, group_id, parent_domain_code, is_core, display_order,
        temporal_model, as_of_date_granularity, as_of_date_label)
    SELECT 'OCIO_TARGET', 'Allocation Target',
           'A client program''s or mandate sleeve''s target at one level of the Strategy, Region or Structure hierarchy, for the total program, or for one deployment year.',
           v_client, f.group_id, 'FUND', FALSE, f.display_order + 1, p.temporal_model, p.as_of_date_granularity, p.as_of_date_label
    FROM metadata_register.domain_types f CROSS JOIN metadata_register.domain_types p
    WHERE f.domain_code = 'FUND' AND p.domain_code = 'DEAL_FUNDING_PLAN'
    ON CONFLICT (domain_code) DO UPDATE SET
        domain_name = EXCLUDED.domain_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id,
        group_id = EXCLUDED.group_id, parent_domain_code = EXCLUDED.parent_domain_code, updated_at = now();

    -- ---------- reference lists ----------
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_STRATEGY_TREE', 'OCIO strategy tree', 'SECURITY', 'Asset class, strategy and sub-strategy for OCIO targets.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_STRUCTURE_TREE', 'OCIO structure tree', 'SECURITY', 'Category, structure type and structure detail for OCIO targets.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_REGION', 'OCIO region', 'SECURITY', 'Regions OCIO targets are set against.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_TARGET_BASIS', 'OCIO target percent basis', 'FUND', 'What a percent target is a share of.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_TARGET_HIERARCHY', 'OCIO target hierarchy', 'OCIO_TARGET', 'Which hierarchy an allocation target is set in.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    INSERT INTO metadata_register.reference_lists (list_code, list_name, domain_code, description, is_active, client_id)
    VALUES ('OCIO_ASSET_TYPE', 'OCIO asset type', 'SECURITY', 'Whether a Harbor Lite security is a fund interest, a direct co-investment or a separate account.', TRUE, v_client)
    ON CONFLICT (list_code) DO UPDATE SET list_name = EXCLUDED.list_name, description = EXCLUDED.description, client_id = EXCLUDED.client_id, updated_at = now();
    CREATE TEMP TABLE t_list_value (list_code text, value_code text, value_label text, parent_code text, level smallint, display_order int) ON COMMIT DROP;
    INSERT INTO t_list_value VALUES
        ('OCIO_STRATEGY_TREE', 'PRIVATE_EQUITY', 'Private Equity', NULL, 1, 1),
        ('OCIO_STRATEGY_TREE', 'BUYOUT', 'Buyout', 'PRIVATE_EQUITY', 2, 2),
        ('OCIO_STRATEGY_TREE', 'SMALL_CAP', 'Small Cap', 'BUYOUT', 3, 3),
        ('OCIO_STRATEGY_TREE', 'MID_CAP', 'Mid Cap', 'BUYOUT', 3, 4),
        ('OCIO_STRATEGY_TREE', 'LARGE_CAP', 'Large Cap', 'BUYOUT', 3, 5),
        ('OCIO_STRATEGY_TREE', 'MEGA', 'Mega', 'BUYOUT', 3, 6),
        ('OCIO_STRATEGY_TREE', 'FOF_MULTI_CAP', 'FoF - Multi-Cap', 'BUYOUT', 3, 7),
        ('OCIO_STRATEGY_TREE', 'GROWTH_EQUITY', 'Growth Equity', 'PRIVATE_EQUITY', 2, 8),
        ('OCIO_STRATEGY_TREE', 'VENTURE_CAPITAL', 'Venture Capital', 'PRIVATE_EQUITY', 2, 9),
        ('OCIO_STRATEGY_TREE', 'SEED_EARLY_STAGE', 'Seed / Early Stage', 'VENTURE_CAPITAL', 3, 10),
        ('OCIO_STRATEGY_TREE', 'LATE_STAGE', 'Late Stage', 'VENTURE_CAPITAL', 3, 11),
        ('OCIO_STRATEGY_TREE', 'MULTI_STAGE', 'Multi-Stage', 'VENTURE_CAPITAL', 3, 12),
        ('OCIO_STRATEGY_TREE', 'GP_STAKES', 'GP Stakes', 'PRIVATE_EQUITY', 2, 13),
        ('OCIO_STRATEGY_TREE', 'FOF_MULTI_STRATEGY_PE', 'FoF - Multi-Strategy PE', 'PRIVATE_EQUITY', 2, 14),
        ('OCIO_STRATEGY_TREE', 'PRIVATE_CREDIT', 'Private Credit', NULL, 1, 15),
        ('OCIO_STRATEGY_TREE', 'ORIGINATION', 'Origination', 'PRIVATE_CREDIT', 2, 16),
        ('OCIO_STRATEGY_TREE', 'SENIOR_DEBT', 'Senior Debt', 'ORIGINATION', 3, 17),
        ('OCIO_STRATEGY_TREE', 'JUNIOR_DEBT', 'Junior Debt', 'ORIGINATION', 3, 18),
        ('OCIO_STRATEGY_TREE', 'STRATEGIC_ORIGINATION', 'Strategic Origination', 'ORIGINATION', 3, 19),
        ('OCIO_STRATEGY_TREE', 'STRUCTURED_PRODUCT', 'Structured Product', 'PRIVATE_CREDIT', 2, 20),
        ('OCIO_STRATEGY_TREE', 'SPECIALTY_FINANCING', 'Specialty Financing', 'PRIVATE_CREDIT', 2, 21),
        ('OCIO_STRATEGY_TREE', 'OPPORTUNISTIC_DEBT', 'Opportunistic Debt', 'PRIVATE_CREDIT', 2, 22),
        ('OCIO_STRATEGY_TREE', 'FOF_MULTI_STRATEGY_PC', 'FoF - Multi-Strategy PC', 'PRIVATE_CREDIT', 2, 23),
        ('OCIO_STRATEGY_TREE', 'PRIVATE_REAL_ASSETS', 'Private Real Assets', NULL, 1, 24),
        ('OCIO_STRATEGY_TREE', 'REAL_ESTATE', 'Real Estate', 'PRIVATE_REAL_ASSETS', 2, 25),
        ('OCIO_STRATEGY_TREE', 'CORE', 'Core', 'REAL_ESTATE', 3, 26),
        ('OCIO_STRATEGY_TREE', 'CORE_PLUS', 'Core Plus', 'REAL_ESTATE', 3, 27),
        ('OCIO_STRATEGY_TREE', 'VALUE_ADD', 'Value Add', 'REAL_ESTATE', 3, 28),
        ('OCIO_STRATEGY_TREE', 'OPPORTUNISTIC', 'Opportunistic', 'REAL_ESTATE', 3, 29),
        ('OCIO_STRATEGY_TREE', 'REAL_ESTATE_DEBT', 'Real Estate Debt', 'REAL_ESTATE', 3, 30),
        ('OCIO_STRATEGY_TREE', 'INFRASTRUCTURE', 'Infrastructure', 'PRIVATE_REAL_ASSETS', 2, 31),
        ('OCIO_STRATEGY_TREE', 'CORE_INFRASTRUCTURE', 'Core Infrastructure', 'INFRASTRUCTURE', 3, 32),
        ('OCIO_STRATEGY_TREE', 'CORE_PLUS_INFRASTRUCTURE', 'Core Plus Infrastructure', 'INFRASTRUCTURE', 3, 33),
        ('OCIO_STRATEGY_TREE', 'VALUE_ADD_INFRASTRUCTURE', 'Value Add Infrastructure', 'INFRASTRUCTURE', 3, 34),
        ('OCIO_STRATEGY_TREE', 'OPPORTUNISTIC_INFRASTRUCTURE', 'Opportunistic Infrastructure', 'INFRASTRUCTURE', 3, 35),
        ('OCIO_STRATEGY_TREE', 'INFRASTRUCTURE_DEBT', 'Infrastructure Debt', 'INFRASTRUCTURE', 3, 36),
        ('OCIO_STRATEGY_TREE', 'NATURAL_RESOURCES', 'Natural Resources', 'PRIVATE_REAL_ASSETS', 2, 37),
        ('OCIO_STRATEGY_TREE', 'ENERGY', 'Energy', 'NATURAL_RESOURCES', 3, 38),
        ('OCIO_STRATEGY_TREE', 'MINING_AND_MINERALS', 'Mining & Minerals', 'NATURAL_RESOURCES', 3, 39),
        ('OCIO_STRATEGY_TREE', 'AGRICULTURE', 'Agriculture', 'NATURAL_RESOURCES', 3, 40),
        ('OCIO_STRATEGY_TREE', 'TIMBERLAND', 'Timberland', 'NATURAL_RESOURCES', 3, 41),
        ('OCIO_STRATEGY_TREE', 'CAPITAL_ASSETS', 'Capital Assets', 'NATURAL_RESOURCES', 3, 42),
        ('OCIO_STRATEGY_TREE', 'FOF_MULTI_STRATEGY_RA', 'FoF - Multi-Strategy RA', 'PRIVATE_REAL_ASSETS', 2, 43),
        ('OCIO_STRATEGY_TREE', 'MULTI_STRATEGY', 'Multi-Strategy', NULL, 1, 44),
        ('OCIO_STRATEGY_TREE', 'MULTI_STRATEGY__MULTI_STRATEGY', 'Multi-Strategy', 'MULTI_STRATEGY', 2, 45),
        ('OCIO_STRATEGY_TREE', 'OTHER_ALTERNATIVES', 'Other Alternatives', NULL, 1, 46),
        ('OCIO_STRATEGY_TREE', 'HEDGE_FUND', 'Hedge Fund', 'OTHER_ALTERNATIVES', 2, 47),
        ('OCIO_STRUCTURE_TREE', 'PRIMARY', 'Primary', NULL, 1, 1),
        ('OCIO_STRUCTURE_TREE', 'TRADITIONAL_PRIMARY', 'Traditional Primary', 'PRIMARY', 2, 2),
        ('OCIO_STRUCTURE_TREE', 'FUND_OF_FUNDS', 'Fund-of-Funds', 'PRIMARY', 2, 3),
        ('OCIO_STRUCTURE_TREE', 'SECONDARY_FUND', 'Secondary Fund', 'PRIMARY', 2, 4),
        ('OCIO_STRUCTURE_TREE', 'CO_INVESTMENT_FUND', 'Co-Investment Fund', 'PRIMARY', 2, 5),
        ('OCIO_STRUCTURE_TREE', 'MULTI_MANAGER_CI', 'Multi-Manager CI', 'CO_INVESTMENT_FUND', 3, 6),
        ('OCIO_STRUCTURE_TREE', 'SINGLE_MANAGER_CI', 'Single Manager CI', 'CO_INVESTMENT_FUND', 3, 7),
        ('OCIO_STRUCTURE_TREE', 'DELAYED_PRIMARY', 'Delayed Primary', 'PRIMARY', 2, 8),
        ('OCIO_STRUCTURE_TREE', 'OPEN_ENDED_EVERGREEN', 'Open-Ended / Evergreen', 'PRIMARY', 2, 9),
        ('OCIO_STRUCTURE_TREE', 'SECONDARY', 'Secondary', NULL, 1, 10),
        ('OCIO_STRUCTURE_TREE', 'LP_LED', 'LP Led', 'SECONDARY', 2, 11),
        ('OCIO_STRUCTURE_TREE', 'SINGLE_FUND', 'Single Fund', 'LP_LED', 3, 12),
        ('OCIO_STRUCTURE_TREE', 'PORTFOLIO', 'Portfolio', 'LP_LED', 3, 13),
        ('OCIO_STRUCTURE_TREE', 'GP_LED', 'GP Led', 'SECONDARY', 2, 14),
        ('OCIO_STRUCTURE_TREE', 'SINGLE_ASSET', 'Single Asset', 'GP_LED', 3, 15),
        ('OCIO_STRUCTURE_TREE', 'MULTI_ASSET', 'Multi Asset', 'GP_LED', 3, 16),
        ('OCIO_STRUCTURE_TREE', 'COMPLEX', 'Complex', 'SECONDARY', 2, 17),
        ('OCIO_STRUCTURE_TREE', 'SECONDARY_DIRECT', 'Secondary Direct', 'COMPLEX', 3, 18),
        ('OCIO_STRUCTURE_TREE', 'PREFERRED_STRUCTURED', 'Preferred / Structured', 'COMPLEX', 3, 19),
        ('OCIO_STRUCTURE_TREE', 'OTHER', 'Other', 'COMPLEX', 3, 20),
        ('OCIO_STRUCTURE_TREE', 'CO_INVESTMENT', 'Co-Investment', NULL, 1, 21),
        ('OCIO_STRUCTURE_TREE', 'CO_INVESTMENT__CO_INVESTMENT', 'Co-Investment', 'CO_INVESTMENT', 2, 22),
        ('OCIO_STRUCTURE_TREE', 'CO_UNDERWRITE', 'Co-Underwrite', 'CO_INVESTMENT', 2, 23),
        ('OCIO_STRUCTURE_TREE', 'CO_LEAD', 'Co-Lead', 'CO_INVESTMENT', 2, 24),
        ('OCIO_STRUCTURE_TREE', 'LEAD', 'Lead', 'CO_INVESTMENT', 2, 25),
        ('OCIO_STRUCTURE_TREE', 'SEPARATE_ACCOUNT', 'Separate Account', NULL, 1, 26),
        ('OCIO_REGION', 'GLOBAL', 'Global', NULL, 1, 1),
        ('OCIO_REGION', 'NORTH_AMERICA', 'North America', NULL, 1, 2),
        ('OCIO_REGION', 'WESTERN_EUROPE', 'Western Europe', NULL, 1, 3),
        ('OCIO_REGION', 'APAC_ROW', 'APAC/ROW', NULL, 1, 4),
        ('OCIO_TARGET_BASIS', 'PROGRAM', 'Share of the total program', NULL, 1, 1),
        ('OCIO_TARGET_BASIS', 'PARENT_LEVEL', 'Share of the level above', NULL, 1, 2),
        ('OCIO_ASSET_TYPE', 'FUND', 'Fund', NULL, 1, 1),
        ('OCIO_ASSET_TYPE', 'DIRECT', 'Direct / Co-Investment', NULL, 1, 2),
        ('OCIO_ASSET_TYPE', 'SEPARATE_ACCOUNT', 'Separate Account', NULL, 1, 3),
        ('OCIO_TARGET_HIERARCHY', 'PROGRAM', 'Total program', NULL, 1, 1),
        ('OCIO_TARGET_HIERARCHY', 'STRATEGY', 'Strategy', NULL, 1, 2),
        ('OCIO_TARGET_HIERARCHY', 'REGION', 'Region', NULL, 1, 3),
        ('OCIO_TARGET_HIERARCHY', 'STRUCTURE', 'Structure', NULL, 1, 4),
        ('OCIO_TARGET_HIERARCHY', 'YEAR', 'Deployment year', NULL, 1, 5);
    INSERT INTO metadata_register.reference_list_values (list_id, value_code, value_label, display_order, is_active, level)
    SELECT l.id, t.value_code, t.value_label, t.display_order, TRUE, t.level
    FROM t_list_value t JOIN metadata_register.reference_lists l ON l.list_code = t.list_code
    WHERE NOT EXISTS (SELECT 1 FROM metadata_register.reference_list_values v WHERE v.list_id = l.id AND v.value_code = t.value_code);
    UPDATE metadata_register.reference_list_values v
    SET value_label = t.value_label, display_order = t.display_order, level = t.level,
        parent_value_id = (SELECT p.id FROM metadata_register.reference_list_values p WHERE p.list_id = v.list_id AND p.value_code = t.parent_code)
    FROM t_list_value t JOIN metadata_register.reference_lists l ON l.list_code = t.list_code
    WHERE v.list_id = l.id AND v.value_code = t.value_code;

    -- ---------- attributes ----------
    CREATE TEMP TABLE t_attr (code text, name text, domain text, dtype text, description text, section text, grp int, editable boolean, list_code text, list_level smallint, controlling text, list_values jsonb, time_varying boolean) ON COMMIT DROP;
    INSERT INTO t_attr VALUES
        ('OCIO_TARGET_INVESTMENT_COUNT', 'Target Investment Count', 'FUND', 'INTEGER', 'Number of investments the client or sleeve plans over its life.', 'OCIO targets', 1, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_ANNUAL_DEPLOYMENT_TARGET', 'Annual Deployment Target', 'FUND', 'CURRENCY', 'Dollars the client or sleeve plans to commit each year.', 'OCIO targets', 1, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_PERCENT_BASIS', 'Target Percent Basis', 'FUND', 'REFERENCE_LIST', 'Whether a percent target is a share of the total program or of the level above.', 'OCIO targets', 1, true, 'OCIO_TARGET_BASIS', 1, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_HIERARCHY', 'Target Hierarchy', 'OCIO_TARGET', 'REFERENCE_LIST', 'The hierarchy the target is set in: Strategy, Region, Structure, the total program, or a deployment year.', 'Target', 1, false, 'OCIO_TARGET_HIERARCHY', 1, NULL, '[]'::jsonb, false),
        ('OCIO_TARGET_LEVEL', 'Target Level', 'OCIO_TARGET', 'STRING', 'The level the target is set at: the codes from the top of the hierarchy down, joined by a slash. TOTAL for the total program; the year for a deployment year.', 'Target', 1, false, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_TARGET_USD_MIN', 'Target Dollars, Minimum', 'OCIO_TARGET', 'CURRENCY', 'The least the fund means to commit at this level, in dollars.', 'Dollars', 2, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_USD', 'Target Dollars', 'OCIO_TARGET', 'CURRENCY', 'What the fund means to commit at this level, in dollars. For a deployment year, that year''s deployment target.', 'Dollars', 2, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_USD_MAX', 'Target Dollars, Maximum', 'OCIO_TARGET', 'CURRENCY', 'The most the fund means to commit at this level, in dollars.', 'Dollars', 2, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_COUNT_MIN', 'Target Investments, Minimum', 'OCIO_TARGET', 'INTEGER', 'The fewest investments the fund means to make at this level.', 'Investments', 3, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_COUNT', 'Target Investments', 'OCIO_TARGET', 'INTEGER', 'The number of investments the fund means to make at this level.', 'Investments', 3, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_COUNT_MAX', 'Target Investments, Maximum', 'OCIO_TARGET', 'INTEGER', 'The most investments the fund means to make at this level.', 'Investments', 3, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_PCT_MIN', 'Target Percent, Minimum', 'OCIO_TARGET', 'PERCENTAGE', 'The smallest share this level should be, in percent points, of the program or of the level above per the fund''s percent basis.', 'Percent', 4, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_PCT', 'Target Percent', 'OCIO_TARGET', 'PERCENTAGE', 'The share this level should be, in percent points, of the program or of the level above per the fund''s percent basis.', 'Percent', 4, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_TARGET_PCT_MAX', 'Target Percent, Maximum', 'OCIO_TARGET', 'PERCENTAGE', 'The largest share this level should be, in percent points, of the program or of the level above per the fund''s percent basis.', 'Percent', 4, true, NULL, NULL, NULL, '[]'::jsonb, true),
        ('OCIO_ASSET_TYPE', 'Asset Type', 'SECURITY', 'REFERENCE_LIST', 'Fund, Direct / Co-Investment or Separate Account. Fund interests use the Harbor Lite Fund template.', 'OCIO classification', 1, true, 'OCIO_ASSET_TYPE', 1, NULL, '[]'::jsonb, false),
        ('OCIO_CATEGORY', 'OCIO Category', 'SECURITY', 'REFERENCE_LIST', 'Primary, Secondary, Co-Investment or Separate Account.', 'OCIO classification', 1, true, 'OCIO_STRUCTURE_TREE', 1, NULL, '[]'::jsonb, false),
        ('OCIO_ASSET_CLASS', 'OCIO Asset Class', 'SECURITY', 'REFERENCE_LIST', 'Asset class in the OCIO strategy tree.', 'OCIO classification', 1, true, 'OCIO_STRATEGY_TREE', 1, NULL, '[]'::jsonb, false),
        ('OCIO_STRATEGY', 'OCIO Strategy', 'SECURITY', 'REFERENCE_LIST', 'Strategy under the asset class.', 'OCIO classification', 1, true, 'OCIO_STRATEGY_TREE', 2, 'OCIO_ASSET_CLASS', '[]'::jsonb, false),
        ('OCIO_SUB_STRATEGY', 'OCIO Sub-Strategy', 'SECURITY', 'REFERENCE_LIST', 'Sub-strategy under the strategy.', 'OCIO classification', 1, true, 'OCIO_STRATEGY_TREE', 3, 'OCIO_STRATEGY', '[]'::jsonb, false),
        ('OCIO_REGION', 'OCIO Region', 'SECURITY', 'REFERENCE_LIST', 'Region the investment is classified under.', 'OCIO classification', 1, true, 'OCIO_REGION', 1, NULL, '[]'::jsonb, false),
        ('OCIO_STRUCTURE_TYPE', 'OCIO Structure Type', 'SECURITY', 'REFERENCE_LIST', 'Structure type under the category.', 'OCIO classification', 1, true, 'OCIO_STRUCTURE_TREE', 2, 'OCIO_CATEGORY', '[]'::jsonb, false),
        ('OCIO_STRUCTURE_DETAIL', 'OCIO Structure Detail', 'SECURITY', 'REFERENCE_LIST', 'Structure detail under the structure type.', 'OCIO classification', 1, true, 'OCIO_STRUCTURE_TREE', 3, 'OCIO_STRUCTURE_TYPE', '[]'::jsonb, false),
        ('OCIO_INVESTMENT_TYPE', 'Investment Type', 'SECURITY', 'STRING', 'Security-master investment type (IDN04).', 'OCIO security master', 2, true, NULL, NULL, NULL, '["Co-Investment (Direct)","Primary Fund","Secondary - Single Fund LP Interest","Secondary - GP-Led / Continuation","Credit Investment","Secondary - Portfolio","Fund of Funds"]'::jsonb, false),
        ('OCIO_MARKET', 'Market Classification', 'SECURITY', 'STRING', 'US, non-US developed or emerging market (GEO02).', 'OCIO security master', 2, true, NULL, NULL, NULL, '["Non-US Developed","US","Emerging Market"]'::jsonb, false),
        ('OCIO_COUNTRY_FOCUS', 'Single-Country Focus', 'SECURITY', 'STRING', 'Country the investment is focused on, or None (GEO03).', 'OCIO security master', 2, true, NULL, NULL, NULL, '["None","Japan","China"]'::jsonb, false),
        ('OCIO_GEO_FOCUS', 'Geographic Focus', 'SECURITY', 'STRING', 'Geography the manager invests in.', 'OCIO security master', 2, true, NULL, NULL, NULL, '["Western Europe","US","Asia-Pacific","Canada"]'::jsonb, false),
        ('OCIO_SECTOR', 'Primary Industry Sector', 'SECURITY', 'STRING', 'Primary industry sector (IND01).', 'OCIO security master', 2, true, NULL, NULL, NULL, '["Tobacco","Financials","Diversified","Information Technology","Materials","Real Estate","Health Care","Consumer Discretionary","Utilities","Industrials","Communication Services","Consumer Staples","Energy"]'::jsonb, false),
