        ('OCIO_FIRST_TIME_FUND', 'First-Time Fund', 'SECURITY', 'BOOLEAN', 'Whether this is the manager''s first fund (STR06).', 'OCIO security master', 2, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_RELATIONSHIP', 'Harbor Lite Relationship', 'SECURITY', 'STRING', 'Third party, or managed by or affiliated with Harbor Lite (MGR02).', 'OCIO security master', 2, true, NULL, NULL, NULL, '["Third Party","HL Affiliated","HL Managed"]'::jsonb, false),
        ('OCIO_IS_LISTED', 'Publicly Traded', 'SECURITY', 'BOOLEAN', 'Whether the investment is a listed security.', 'OCIO security master', 2, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_IS_FUND_OF_FUNDS', 'Fund of Funds', 'SECURITY', 'BOOLEAN', 'Whether the investment is itself a fund of funds.', 'OCIO security master', 2, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_VINTAGE', 'Vintage Year', 'SECURITY', 'INTEGER', 'Vintage year of the underlying fund.', 'OCIO security master', 2, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_COMMITMENT_AMOUNT', 'Original Commitment', 'POSITION', 'CURRENCY', 'Dollars the sleeve committed to the investment.', 'OCIO commitment', 1, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_ALLOCATION_YEAR', 'Allocation Tranche', 'POSITION', 'STRING', 'The annual allocation the commitment was made from, for example 2024 Allocation.', 'OCIO commitment', 1, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_IS_FOLLOW_ON', 'Follow-On', 'POSITION', 'BOOLEAN', 'Whether the commitment adds to an existing investment.', 'OCIO commitment', 1, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_CONTRACTUAL_REVIEW', 'Contractual Restriction Review', 'POSITION', 'STRING', 'Cleared or pending (TRM10).', 'OCIO attestations', 2, true, NULL, NULL, NULL, '["Cleared","Pending","Restricted"]'::jsonb, false),
        ('OCIO_ESG_REVIEW', 'ESG Questionnaire', 'POSITION', 'STRING', 'Compliant or pending (EXC14).', 'OCIO attestations', 2, true, NULL, NULL, NULL, '["Compliant","Pending","Non-compliant"]'::jsonb, false),
        ('OCIO_STRATEGY_REVIEW', 'Investment Strategy Questionnaire', 'POSITION', 'STRING', 'Pass, N/A or pending.', 'OCIO attestations', 2, true, NULL, NULL, NULL, '["Pass","N/A","Pending","Fail"]'::jsonb, false),
        ('OCIO_ALLOCATION_AMOUNT', 'Proposed Allocation', 'DEAL_FUNDING_PLAN', 'CURRENCY', 'Dollars of the deal the sleeve is proposed to take.', 'OCIO allocation', 1, true, NULL, NULL, NULL, '[]'::jsonb, false),
        ('OCIO_SHARING_RATIO', 'Sharing Ratio', 'DEAL_FUNDING_PLAN', 'PERCENTAGE', 'The sleeve''s share of the deal when the plan was staged, in percent points.', 'OCIO allocation', 1, false, NULL, NULL, NULL, '[]'::jsonb, false);
    INSERT INTO metadata_register.attribute_register (
        attribute_code, attribute_name, data_type, description, domain_code, client_id,
        display_section, display_group, is_editable, is_visible, is_required, is_multi_valued, is_derived,
        reference_list_code, reference_list_level, controlling_attribute_code, list_values,
        is_time_varying, default_precedence_rank, aggregation_type, metadata)
    SELECT code, name, dtype, description, domain, v_client,
           section, grp, editable, TRUE, FALSE, FALSE, FALSE,
           list_code, list_level, controlling, list_values,
           time_varying, 100, 'NONE', '{"ocio": true}'::jsonb
    FROM t_attr
    ON CONFLICT (attribute_code) DO UPDATE SET
        attribute_name = EXCLUDED.attribute_name, data_type = EXCLUDED.data_type, description = EXCLUDED.description,
        domain_code = EXCLUDED.domain_code, client_id = EXCLUDED.client_id, display_section = EXCLUDED.display_section,
        display_group = EXCLUDED.display_group, is_editable = EXCLUDED.is_editable,
        reference_list_code = EXCLUDED.reference_list_code, reference_list_level = EXCLUDED.reference_list_level,
        controlling_attribute_code = EXCLUDED.controlling_attribute_code, list_values = EXCLUDED.list_values,
        is_time_varying = EXCLUDED.is_time_varying, updated_at = now();

    -- ---------- security template: Fund ----------
    -- Harbor Lite's layout for a fund interest. A security uses it when its asset
    -- type is Fund; the sample records below are given it by the same rule.
    INSERT INTO metadata_register.domain_templates (
        template_code, domain_code, template_name, description, is_active, client_id, scope,
        based_on_template_id, applicability_rules, qualification_priority, precedence_rules, metadata)
    VALUES ('OCIO_SECURITY_FUND', 'SECURITY', 'Fund',
        'A fund interest: primary fund, secondary or fund of funds. Identification, the OCIO classification, the fund terms the guidelines test, and geography and sector.',
        TRUE, v_client, 'DOMAIN',
        (SELECT id FROM metadata_register.domain_templates WHERE template_code = 'SECURITY_STANDARD'),
        '{"logic": "AND", "conditions": [{"attributeCode": "OCIO_ASSET_TYPE", "operator": "EQUALS", "value": "FUND"}]}'::jsonb,
        50, '{}'::jsonb, '{"ocio": true}'::jsonb)
    ON CONFLICT (template_code) DO UPDATE SET
        template_name = EXCLUDED.template_name, description = EXCLUDED.description, is_active = TRUE,
        client_id = EXCLUDED.client_id, based_on_template_id = EXCLUDED.based_on_template_id,
        applicability_rules = EXCLUDED.applicability_rules, qualification_priority = EXCLUDED.qualification_priority,
        metadata = EXCLUDED.metadata, updated_at = now();
    CREATE TEMP TABLE t_tpl_section (section_code text, section_name text, description text, display_order int) ON COMMIT DROP;
    INSERT INTO t_tpl_section VALUES
        ('IDENTIFICATION', 'Identification', 'Which fund this is and who manages it.', 1),
        ('CLASSIFICATION', 'OCIO classification', 'Where the fund sits in the Structure, Strategy and Region hierarchies targets are set against.', 2),
        ('FUND_TERMS', 'Fund terms', 'Facts about the underlying fund that the mandate guidelines test.', 3),
        ('GEOGRAPHY_SECTOR', 'Geography and sector', 'Where and in what the manager invests.', 4);
    INSERT INTO metadata_register.template_sections (template_id, section_code, section_name, description, display_order)
    SELECT dt.id, s.section_code, s.section_name, s.description, s.display_order
    FROM t_tpl_section s CROSS JOIN metadata_register.domain_templates dt
    WHERE dt.template_code = 'OCIO_SECURITY_FUND'
    ON CONFLICT (template_id, section_code) DO UPDATE SET
        section_name = EXCLUDED.section_name, description = EXCLUDED.description,
        display_order = EXCLUDED.display_order, updated_at = now();
    CREATE TEMP TABLE t_tpl_attr (section_code text, attribute_code text, display_label text, is_required boolean, display_order int) ON COMMIT DROP;
