    DELETE FROM metadata_register.template_attribute_assignments a
    USING metadata_register.domain_templates dt, metadata_register.attribute_register ar
    WHERE a.template_id = dt.id AND dt.template_code = 'OCIO_SECURITY_FUND' AND ar.id = a.attribute_id
      AND ar.attribute_code NOT IN (SELECT attribute_code FROM t_tpl_attr);
    INSERT INTO metadata_register.template_attribute_assignments (
        template_id, attribute_id, section_id, display_label, is_required, display_order, precedence_rank)
    SELECT dt.id, ar.id, ts.id, t.display_label, t.is_required, (ts.display_order * 100) + t.display_order, 100
    FROM t_tpl_attr t
    JOIN metadata_register.domain_templates dt ON dt.template_code = 'OCIO_SECURITY_FUND'
    JOIN metadata_register.template_sections ts ON ts.template_id = dt.id AND ts.section_code = t.section_code
    JOIN metadata_register.attribute_register ar ON ar.attribute_code = t.attribute_code
    ON CONFLICT (template_id, attribute_id) DO UPDATE SET
        section_id = EXCLUDED.section_id, display_label = EXCLUDED.display_label,
        is_required = EXCLUDED.is_required, display_order = EXCLUDED.display_order;

    -- ---------- allocation target: template and link to its fund ----------
    INSERT INTO metadata_register.domain_templates (template_code, domain_code, template_name, description, is_active, client_id, scope, metadata)
    VALUES ('OCIO_TARGET_STANDARD', 'OCIO_TARGET', 'Allocation Target',
        'Where the target is set, and its minimum, target and maximum in dollars, investments and percent.', TRUE, v_client, 'DOMAIN', '{"ocio": true}'::jsonb)
    ON CONFLICT (template_code) DO UPDATE SET
        template_name = EXCLUDED.template_name, description = EXCLUDED.description, is_active = TRUE,
        client_id = EXCLUDED.client_id, metadata = EXCLUDED.metadata, updated_at = now();
    INSERT INTO metadata_register.template_attribute_assignments (template_id, attribute_id, is_required, display_order, precedence_rank)
    SELECT dt.id, ar.id, ar.attribute_code IN ('OCIO_TARGET_HIERARCHY', 'OCIO_TARGET_LEVEL'), a.ord::int, 100
    FROM unnest(ARRAY['OCIO_TARGET_HIERARCHY', 'OCIO_TARGET_LEVEL', 'OCIO_TARGET_USD_MIN', 'OCIO_TARGET_USD', 'OCIO_TARGET_USD_MAX',
                      'OCIO_TARGET_COUNT_MIN', 'OCIO_TARGET_COUNT', 'OCIO_TARGET_COUNT_MAX',
                      'OCIO_TARGET_PCT_MIN', 'OCIO_TARGET_PCT', 'OCIO_TARGET_PCT_MAX']) WITH ORDINALITY a(code, ord)
    JOIN metadata_register.attribute_register ar ON ar.attribute_code = a.code
    JOIN metadata_register.domain_templates dt ON dt.template_code = 'OCIO_TARGET_STANDARD'
    ON CONFLICT (template_id, attribute_id) DO UPDATE SET is_required = EXCLUDED.is_required, display_order = EXCLUDED.display_order;
    INSERT INTO metadata_register.relationship_types (
        relationship_code, relationship_name, parent_domain_code, child_domain_code, description, cardinality, is_required, client_id)
    VALUES ('OCIO_TARGET_FUND', 'Target of fund', 'OCIO_TARGET', 'FUND', 'The client program or mandate sleeve the target belongs to.', 'MANY_TO_ONE', TRUE, v_client)
    ON CONFLICT (relationship_code) DO UPDATE SET
        relationship_name = EXCLUDED.relationship_name, parent_domain_code = EXCLUDED.parent_domain_code,
        child_domain_code = EXCLUDED.child_domain_code, description = EXCLUDED.description,
        cardinality = EXCLUDED.cardinality, is_required = EXCLUDED.is_required, client_id = EXCLUDED.client_id;

