    CREATE TEMP TABLE t_target_record ON COMMIT DROP AS
    SELECT DISTINCT fund_code, hierarchy, level,
           fund_code || '-T-' || hierarchy || '-' || substr(md5(level), 1, 10) AS entity_code
    FROM t_target;
    INSERT INTO t_ent
    SELECT r.entity_code, 'OCIO_TARGET', 'OCIO_TARGET_STANDARD',
           left(f.entity_name || ' · ' || h.value_label || CASE WHEN r.hierarchy = 'PROGRAM' THEN '' ELSE ' · ' || (
               SELECT string_agg(COALESCE((SELECT lv.value_label FROM t_list_value lv WHERE lv.value_code = part.code ORDER BY lv.list_code LIMIT 1), part.code), ' › ' ORDER BY part.ord)
               FROM unnest(string_to_array(r.level, '/')) WITH ORDINALITY part(code, ord)) END, 240),
           'Allocation target of ' || f.entity_name || '.'
    FROM t_target_record r
    JOIN t_ent f ON f.entity_code = r.fund_code
    JOIN t_list_value h ON h.list_code = 'OCIO_TARGET_HIERARCHY' AND h.value_code = r.hierarchy;

    INSERT INTO entity_instances.master_entities (entity_code, domain_code, template_id, entity_name, description, client_id, is_active, metadata)
    SELECT t.entity_code, t.domain_code, dt.id, t.entity_name, t.description, v_client, TRUE, '{"ocioSample": true}'::jsonb
    FROM t_ent t LEFT JOIN metadata_register.domain_templates dt ON dt.template_code = t.template_code
    ON CONFLICT (client_id, entity_code) DO UPDATE SET entity_name = EXCLUDED.entity_name, description = EXCLUDED.description,
        template_id = COALESCE(EXCLUDED.template_id, master_entities.template_id), is_active = TRUE, updated_at = now();

