    INSERT INTO t_val
    SELECT entity_code, 'OCIO_TARGET_HIERARCHY', hierarchy FROM t_target_record
    UNION ALL SELECT entity_code, 'OCIO_TARGET_LEVEL', level FROM t_target_record
    UNION ALL SELECT r.entity_code, t.attribute_code, t.val
              FROM t_target t JOIN t_target_record r ON r.fund_code = t.fund_code AND r.hierarchy = t.hierarchy AND r.level = t.level;

    -- ---------- issuers: one record per manager ----------
    -- Every security names its manager. Each manager becomes an issuer record, and each
    -- security is linked to it below, so no security exists without an issuer.
    CREATE TEMP TABLE t_issuer ON COMMIT DROP AS
    SELECT DISTINCT btrim(v.val) AS manager,
           left('OCIO-ISS-' || upper(regexp_replace(btrim(v.val), '[^A-Za-z0-9]+', '-', 'g')), 100) AS entity_code
    FROM t_val v
    WHERE v.attribute_code = 'SECURITY_ISSUER_NAME' AND btrim(v.val) <> '';
    INSERT INTO entity_instances.master_entities (entity_code, domain_code, template_id, entity_name, description, client_id, is_active, metadata)
    SELECT i.entity_code, 'ISSUER', dt.id, i.manager, 'Manager of funds and investments held by Harbor Lite''s programs.', v_client, TRUE, '{"ocioSample": true}'::jsonb
    FROM t_issuer i LEFT JOIN metadata_register.domain_templates dt ON dt.template_code = 'ISSUER_STANDARD'
    ON CONFLICT (client_id, entity_code) DO UPDATE SET entity_name = EXCLUDED.entity_name, description = EXCLUDED.description,
        template_id = COALESCE(EXCLUDED.template_id, master_entities.template_id), is_active = TRUE, updated_at = now();

    -- Sample values are written as the internal source. Rerunning replaces them.
    DELETE FROM golden_master.entity_attribute_values eav
    USING entity_instances.master_entities me
    WHERE eav.entity_id = me.id AND me.client_id = v_client AND me.entity_code LIKE 'OCIO-%'
      AND eav.source_id = v_src;

    INSERT INTO golden_master.entity_attribute_values (
        entity_id, attribute_id, source_id, golden_value,
        golden_value_numeric, golden_value_date, golden_value_boolean, golden_value_jsonb,
        valid_from, valid_to, precedence_rank, metadata
    )
    SELECT me.id, ar.id, v_src, v.val,
           CASE WHEN ar.data_type IN ('NUMBER', 'CURRENCY', 'PERCENTAGE', 'INTEGER', 'DECIMAL') AND v.val ~ '^-?[0-9]+(\.[0-9]+)?$' THEN v.val::numeric END,
           CASE WHEN ar.data_type = 'DATE' AND v.val ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN v.val::date END,
           CASE WHEN ar.data_type = 'BOOLEAN' THEN v.val::boolean END,
           CASE WHEN ar.data_type = 'JSON' THEN v.val::jsonb END,
           DATE '2020-01-01', DATE '9999-12-31', 100, '{"ocioSample": true}'::jsonb
    FROM t_val v
    JOIN entity_instances.master_entities me ON me.entity_code = v.entity_code AND me.client_id = v_client
    JOIN metadata_register.attribute_register ar ON ar.attribute_code = v.attribute_code;

    CREATE TEMP TABLE t_rel (parent_code text, child_code text, rel_code text) ON COMMIT DROP;
