    INSERT INTO t_rel SELECT entity_code, fund_code, 'OCIO_TARGET_FUND' FROM t_target_record;
    INSERT INTO t_rel
    SELECT v.entity_code, i.entity_code, 'SECURITY_ISSUER'
    FROM t_val v JOIN t_issuer i ON i.manager = btrim(v.val)
    WHERE v.attribute_code = 'SECURITY_ISSUER_NAME';
    INSERT INTO entity_instances.entity_relationships (
        parent_entity_id, child_entity_id, relationship_type, relationship_code, is_primary, valid_from, valid_to, metadata)
    SELECT p.id, c.id, rt.relationship_name, t.rel_code, TRUE, DATE '2020-01-01', DATE '9999-12-31', '{"ocioSample": true}'::jsonb
    FROM t_rel t
    JOIN entity_instances.master_entities p ON p.entity_code = t.parent_code AND p.client_id = v_client
    JOIN entity_instances.master_entities c ON c.entity_code = t.child_code AND c.client_id = v_client
    JOIN metadata_register.relationship_types rt ON rt.relationship_code = t.rel_code
    WHERE NOT EXISTS (
        SELECT 1 FROM entity_instances.entity_relationships r
        WHERE r.parent_entity_id = p.id AND r.child_entity_id = c.id AND r.relationship_code = t.rel_code
    );

    -- ---------- retire the JSON target attributes ----------
    -- An earlier version of this seed kept every target of a fund in one JSON value, and its
    -- yearly deployment targets in another. Both are replaced by allocation target records.
    DELETE FROM golden_master.entity_attribute_values eav
    USING metadata_register.attribute_register ar
    WHERE eav.attribute_id = ar.id AND ar.client_id = v_client
      AND ar.attribute_code IN ('OCIO_TARGET_MATRIX', 'OCIO_PACING_OVERRIDES');
    DELETE FROM metadata_register.template_attribute_assignments a
    USING metadata_register.attribute_register ar
    WHERE a.attribute_id = ar.id AND ar.client_id = v_client
      AND ar.attribute_code IN ('OCIO_TARGET_MATRIX', 'OCIO_PACING_OVERRIDES');
    DELETE FROM metadata_register.attribute_register
    WHERE client_id = v_client AND attribute_code IN ('OCIO_TARGET_MATRIX', 'OCIO_PACING_OVERRIDES');

    -- ---------- compliance rules ----------
    -- One rule per workbook test. A sleeve is scored on a rule when it has its own
    -- threshold row (applies = TRUE), so each sleeve carries only its own rules and limits.
    CREATE TEMP TABLE t_rule (
        rule_code text, rule_name text, category text, description text,
        group_attr text, group_path jsonb, num_attr text, num_agg text,
        den_attr text, den_source text, unit text, direction text, metadata jsonb) ON COMMIT DROP;
    INSERT INTO t_rule VALUES
        ('OCIO_ASSET_CONCENTRATION_PCT', 'Asset Concentration (% limit)', 'CONCENTRATION', 'Commitments to one underlying asset over the program size.', 'SECURITY_LABEL', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'FUND_TOTAL_COMMITMENTS', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Asset Concentration (% limit)","dimension_label":"Underlying asset","group_label":"Underlying asset"}'::jsonb),
        ('OCIO_ASSET_CONCENTRATION_AMT', 'Asset Concentration (amount limit)', 'CONCENTRATION', 'Dollars committed to one underlying asset.', 'SECURITY_LABEL', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', NULL, NULL, 'CURRENCY', 'MAX', '{"workbook_name":"Asset Concentration (amount limit)","dimension_label":"Underlying asset","group_label":"Underlying asset"}'::jsonb),
        ('OCIO_MANAGER_CONCENTRATION_PCT', 'Issuer Concentration (% limit)', 'CONCENTRATION', 'Commitments to one manager or GP firm over the program size.', 'SECURITY_ISSUER_NAME', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'FUND_TOTAL_COMMITMENTS', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Issuer Concentration (% limit)","dimension_label":"Manager / GP firm","group_label":"Manager / GP firm"}'::jsonb),
        ('OCIO_SHARE_OF_FUND_SIZE', 'Percent of Total Fund Size (% limit)', 'CONCENTRATION', 'Commitments to one underlying fund as a percent of the fund size. A fund with no size recorded is not measured.', 'SECURITY_LABEL', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'OCIO_UNDERLYING_FUND_SIZE', 'GROUP', 'PERCENTAGE', 'MAX', '{"workbook_name":"Percent of Total Fund Size (% limit)","dimension_label":"Commitment / underlying fund size","group_label":"Commitment / underlying fund size"}'::jsonb),
        ('OCIO_REMAINING_ALLOCATION', 'Remaining Allocation', 'EXPOSURE', 'Commitments in each annual allocation over the annual deployment target.', 'OCIO_ALLOCATION_YEAR', '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'OCIO_ANNUAL_DEPLOYMENT_TARGET', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Remaining Allocation","dimension_label":"Annual allocation (tranche)","group_label":"Annual allocation (tranche)"}'::jsonb),
        ('OCIO_INVESTMENT_SIZE', 'Investment Size', 'CONCENTRATION', 'Dollars of a single commitment.', 'SECURITY_LABEL', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', NULL, NULL, 'CURRENCY', 'MAX', '{"workbook_name":"Investment Size","dimension_label":"Single commitment","group_label":"Single commitment"}'::jsonb),
        ('OCIO_PRIMARY_COUNT_MIN', 'Number of Primary Investments (minimum)', 'DIVERSIFICATION', 'Number of primary fund commitments, at least the minimum.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MIN', '{"workbook_name":"Number of Primary Investments (minimum)","dimension_label":"Primary fund commitments","group_label":"Primary fund commitments"}'::jsonb),
        ('OCIO_PRIMARY_COUNT_MAX', 'Number of Primary Investments (maximum)', 'DIVERSIFICATION', 'Number of primary fund commitments, at most the maximum.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MAX', '{"workbook_name":"Number of Primary Investments (maximum)","dimension_label":"Primary fund commitments","group_label":"Primary fund commitments"}'::jsonb),
        ('OCIO_NON_US_PCT', 'Non-US Investments (% limit)', 'EXPOSURE', 'Non-US commitments over the program size.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'FUND_TOTAL_COMMITMENTS', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Non-US Investments (% limit)","dimension_label":"Non-US commitments","group_label":"Non-US commitments"}'::jsonb),
        ('OCIO_EMERGING_MARKETS_PCT', 'Emerging Markets', 'EXPOSURE', 'Emerging-market commitments over the program size.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'FUND_TOTAL_COMMITMENTS', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Emerging Markets","dimension_label":"Emerging-market commitments","group_label":"Emerging-market commitments"}'::jsonb),
