        ('OCIO_INDUSTRY_CONCENTRATION', 'Industry Concentration', 'CONCENTRATION', 'Commitments in one primary industry sector over the program size. Diversified is not a sector.', 'OCIO_SECTOR', '[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'SUM', 'FUND_TOTAL_COMMITMENTS', NULL, 'PERCENTAGE', 'MAX', '{"workbook_name":"Industry Concentration","dimension_label":"Primary industry sector","group_label":"Primary industry sector"}'::jsonb),
