        ('OCIO_NO_REAL_ESTATE', 'No Real Estate Funds', 'ELIGIBILITY', 'Real estate commitments. None are allowed.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MAX', '{"workbook_name":"No Real Estate Funds","dimension_label":"Real estate commitments","group_label":"Real estate commitments","pass_if_empty":true}'::jsonb),
        ('OCIO_RESTRICTED_INDUSTRIES', 'Restricted Industries', 'ELIGIBILITY', 'Commitments in restricted sectors. None are allowed.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MAX', '{"workbook_name":"Restricted Industries","dimension_label":"Commitments in restricted sectors","group_label":"Commitments in restricted sectors","pass_if_empty":true}'::jsonb),
