        ('OCIO_NO_LISTED', 'Cannot invest in publicly traded securities', 'ELIGIBILITY', 'Publicly traded securities. None are allowed.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MAX', '{"workbook_name":"Cannot invest in publicly traded securities","dimension_label":"Listed securities","group_label":"Listed securities","pass_if_empty":true}'::jsonb),
