        ('OCIO_STRATEGY_REVIEW', 'Manual Rule 2 - Investment Strategy', 'OTHER', 'Commitments whose investment strategy questionnaire has not passed.', NULL, '[]'::jsonb, 'OCIO_COMMITMENT_AMOUNT', 'COUNT', NULL, NULL, 'COUNT', 'MAX', '{"workbook_name":"Manual Rule 2 - Investment Strategy","dimension_label":"Investment strategy questionnaire","group_label":"Investment strategy questionnaire","pass_if_empty":true,"attestation":true}'::jsonb);
    INSERT INTO compliance.rules (rule_code, rule_name, rule_category, anchor_domain_code, applies_to_all, is_active, description, client_id, metadata)
    SELECT rule_code, rule_name, category, 'FUND', FALSE, TRUE, description, v_client, metadata
    FROM t_rule t
    WHERE NOT EXISTS (SELECT 1 FROM compliance.rules r WHERE r.rule_code = t.rule_code AND r.client_id = v_client);
    UPDATE compliance.rules r SET rule_name = t.rule_name, rule_category = t.category, description = t.description, metadata = t.metadata, is_active = TRUE, updated_at = now()
    FROM t_rule t WHERE r.rule_code = t.rule_code AND r.client_id = v_client;

    -- Version 1 of each rule. A rule that already has a version keeps it; change a rule
    -- through the rule editor so its history is kept.
    INSERT INTO compliance.rule_versions (
        rule_id, version_number, valid_from, rule_name, description, base_domain_code, base_rollup_path,
        group_by_attribute_code, group_by_path, numerator_attribute_code, numerator_aggregation,
        denominator_attribute_code, denominator_aggregation, denominator_source, denominator_scope,
        result_transform, result_unit, limit_direction, default_source_scope, consolidate_descendants, is_active, metadata)
    SELECT r.id, 1, DATE '2020-01-01', t.rule_name, t.description, 'POSITION',
           '[{"relationship_code":"POSITION_FUND","direction":"UP","recursive":false}]'::jsonb,
           t.group_attr, t.group_path, t.num_attr, t.num_agg,
           t.den_attr, CASE WHEN t.den_attr IS NOT NULL THEN 'VALUE' END,
           COALESCE(t.den_source, CASE WHEN t.den_attr IS NOT NULL THEN 'ANCHOR' ELSE 'BASE' END), 'SAME_GROUP',
           'NONE', t.unit, t.direction, 'GOLDEN', FALSE, TRUE, t.metadata
    FROM t_rule t JOIN compliance.rules r ON r.rule_code = t.rule_code AND r.client_id = v_client
    WHERE NOT EXISTS (SELECT 1 FROM compliance.rule_versions v WHERE v.rule_id = r.id);

    CREATE TEMP TABLE t_cond (rule_code text, ord int, attribute_code text, operator text, value text, dimension jsonb) ON COMMIT DROP;
    INSERT INTO t_cond VALUES
        ('OCIO_PRIMARY_COUNT_MIN', 1, 'OCIO_INVESTMENT_TYPE', 'equals', 'Primary Fund', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_PRIMARY_COUNT_MAX', 1, 'OCIO_INVESTMENT_TYPE', 'equals', 'Primary Fund', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_NON_US_PCT', 1, 'OCIO_MARKET', 'not_equals', 'US', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_EMERGING_MARKETS_PCT', 1, 'OCIO_MARKET', 'equals', 'Emerging Market', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_SECONDARIES_PCT', 1, 'OCIO_CATEGORY', 'equals', 'SECONDARY', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_VENTURE_PCT', 1, 'OCIO_STRATEGY', 'equals', 'VENTURE_CAPITAL', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_INDUSTRY_CONCENTRATION', 1, 'OCIO_SECTOR', 'not_equals', 'Diversified', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_CHINA_PRIMARIES_PCT', 1, 'OCIO_COUNTRY_FOCUS', 'equals', 'China', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_CHINA_PRIMARIES_PCT', 2, 'OCIO_INVESTMENT_TYPE', 'in', '["Primary Fund","Co-Investment (Direct)"]', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_AFFILIATED_PCT', 1, 'OCIO_RELATIONSHIP', 'not_equals', 'Third Party', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_NO_REAL_ESTATE', 1, 'OCIO_STRATEGY', 'equals', 'REAL_ESTATE', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_RESTRICTED_INDUSTRIES', 1, 'OCIO_SECTOR', 'in', '["Tobacco","Energy"]', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_NO_FUND_OF_FUNDS', 1, 'OCIO_IS_FUND_OF_FUNDS', 'equals', 'true', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_NO_LISTED', 1, 'OCIO_IS_LISTED', 'equals', 'true', '{"relationship_path":[{"relationship_code":"POSITION_SECURITY","direction":"DOWN","recursive":false}]}'::jsonb),
        ('OCIO_CONTRACTUAL_REVIEW', 1, 'OCIO_CONTRACTUAL_REVIEW', 'not_equals', 'Cleared', '{}'::jsonb),
        ('OCIO_ESG_REVIEW', 1, 'OCIO_ESG_REVIEW', 'not_equals', 'Compliant', '{}'::jsonb),
        ('OCIO_STRATEGY_REVIEW', 1, 'OCIO_STRATEGY_REVIEW', 'not_in', '["Pass","N/A"]', '{}'::jsonb);
    INSERT INTO compliance.rule_conditions (rule_version_id, applies_to, condition_group, condition_order, attribute_code, operator, value, logic_operator, attribute_dimension, filter_role)
    SELECT v.id, 'BASE', 1, t.ord, t.attribute_code, t.operator, t.value, 'AND', t.dimension, 'WHERE'
    FROM t_cond t
    JOIN compliance.rules r ON r.rule_code = t.rule_code AND r.client_id = v_client
    JOIN compliance.rule_versions v ON v.rule_id = r.id AND v.version_number = 1
    WHERE NOT EXISTS (SELECT 1 FROM compliance.rule_conditions c WHERE c.rule_version_id = v.id AND c.condition_order = t.ord);

    CREATE TEMP TABLE t_threshold (rule_code text, fund_code text, soft numeric, hard numeric, direction text) ON COMMIT DROP;
    INSERT INTO t_threshold VALUES
        ('OCIO_ASSET_CONCENTRATION_PCT', 'OCIO-CTR-PE', NULL, 5, 'MAX'),
