    DELETE FROM compliance.rule_thresholds th
    USING compliance.rules r
    WHERE th.rule_id = r.id AND r.client_id = v_client AND r.rule_code LIKE 'OCIO\_%';
    INSERT INTO compliance.rule_thresholds (rule_id, entity_id, soft_limit_value, hard_limit_value, applies, limit_direction, valid_from, valid_to, notes)
    SELECT r.id, me.id, t.soft, t.hard, TRUE, t.direction, DATE '2020-01-01', DATE '9999-12-31', 'OCIO workbook limit for this sleeve.'
    FROM t_threshold t
    JOIN compliance.rules r ON r.rule_code = t.rule_code AND r.client_id = v_client
    JOIN entity_instances.master_entities me ON me.entity_code = t.fund_code AND me.client_id = v_client;

    DELETE FROM compliance.rule_scope_assignments sa
    USING compliance.rules r
    WHERE sa.rule_id = r.id AND r.client_id = v_client AND r.rule_code LIKE 'OCIO\_%';
    INSERT INTO compliance.rule_scope_assignments (rule_id, scope_type, entity_id, include_children, notes)
    SELECT DISTINCT r.id, 'INCLUDE', me.id, FALSE, 'OCIO sleeve'
    FROM t_threshold t
    JOIN compliance.rules r ON r.rule_code = t.rule_code AND r.client_id = v_client
    JOIN entity_instances.master_entities me ON me.entity_code = t.fund_code AND me.client_id = v_client;

    -- ---------- module: the surface and the entity types it reads ----------
    INSERT INTO tenancy.module_catalog (module_code, module_name, description, display_order, domain_codes, surface_codes, workflow_codes, tool_hrefs)
    VALUES ('ocio', 'OCIO mandate targets', 'Targets, pacing, compliance and deal allocation across client programs and mandate sleeves.', 90,
            ARRAY['FUND', 'POSITION', 'ISSUER', 'SECURITY', 'DEAL', 'DEAL_TRANCHE', 'DEAL_FUNDING_PLAN', 'OCIO_TARGET'], ARRAY['ocio'], ARRAY[]::text[], ARRAY['/s/ocio'])
    ON CONFLICT (module_code) DO UPDATE SET module_name = EXCLUDED.module_name, description = EXCLUDED.description,
        domain_codes = EXCLUDED.domain_codes, surface_codes = EXCLUDED.surface_codes, tool_hrefs = EXCLUDED.tool_hrefs;

    INSERT INTO tenancy.client_modules (client_id, module_code) VALUES (v_client, 'ocio') ON CONFLICT DO NOTHING;
    INSERT INTO tenancy.client_module_grants (client_id, kind, code)
    SELECT v_client, 'domain', unnest(ARRAY['FUND', 'POSITION', 'ISSUER', 'SECURITY', 'DEAL', 'DEAL_TRANCHE', 'DEAL_FUNDING_PLAN', 'OCIO_TARGET'])
    ON CONFLICT DO NOTHING;
    INSERT INTO tenancy.client_module_grants (client_id, kind, code) VALUES (v_client, 'surface', 'ocio'), (v_client, 'tool', '/s/ocio')
    ON CONFLICT DO NOTHING;

    -- Harbor Lite works across the whole catalog, not only the OCIO screen: the system's
    -- securities, market data and deal entity types are turned on with everything in them, so
    -- no granted type is left without the type above it (Security under Issuer).
    INSERT INTO tenancy.client_modules (client_id, module_code)
    SELECT v_client, m.module_code FROM tenancy.module_catalog m WHERE m.module_code IN ('securities', 'market_data', 'deals')
    ON CONFLICT DO NOTHING;
    INSERT INTO tenancy.client_module_grants (client_id, kind, code)
    SELECT v_client, g.kind, g.code
    FROM tenancy.module_catalog m
    CROSS JOIN LATERAL (
        SELECT 'domain' AS kind, unnest(m.domain_codes) AS code
        UNION ALL SELECT 'surface', unnest(m.surface_codes)
        UNION ALL SELECT 'workflow', unnest(m.workflow_codes)
        UNION ALL SELECT 'tool', unnest(m.tool_hrefs)
    ) g
    WHERE m.module_code IN ('securities', 'market_data', 'deals')
    ON CONFLICT DO NOTHING;
END $$;
